                    "scopes": list(dwd.scopes),
                    "token_expires_at": dwd.token_expires_at.ToDatetime() if dwd.HasField("token_expires_at") else None,
                }
                authorization_details["google_dwd"] = dwd_dict
            elif which == "trusted_idp":
