                authorization_details["trusted_idp"] = {
                    "db_user": idp.db_user,
                    "access_key_id": idp.access_key_id,
                    "secret_access_key": idp.secret_access_key,
                    "session_token": idp.session_token,
                    "expiry": idp.expiry.ToDatetime() if idp.HasField("expiry") else None,
                }

